from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class NrcellFddParamsGenerator(ManagedObject):

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.cell_ent = self.enb_ent_config['cells'][self.cell_num]
        self.ch_bw = None

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        self.set_parameter('chBwDl', self.cell_ent['ch_bw'])
        self.set_parameter('chBwUl', self.cell_ent['ch_bw'])
        self.set_parameter('nrarfcnDl', self.cell_ent['earfcn_dl'])
        self.set_parameter('nrarfcnUl', self.cell_ent['earfcn_ul'])
